/* Live controls on the unmodified v5 prototype; all persistent state comes from the TS server. */
'use strict';
const native={routes:[],services:[],agents:[],templates:[],sources:null,sentiment:null,dashboard:null,signals:[],approvals:[],recordFilter:'all'};
const nativeLabels={chat:'对话问答',planner:'主 Agent / 规划与门禁',insight:'Insight 查库',media:'Media 外部调查',query:'Query 新闻调查',forum:'ForumHost 主持',report:'Report 完整成稿',keyword:'关键词优化（保留槽）',mindspider:'话题与关键词种子（保留槽）'};
const nativeDefaults={tavily:'https://api.tavily.com/search',bocha:'https://api.bochaai.com/v1/web-search',anspire:'https://plugin.anspire.cn/api/ntsearch/search',firecrawl:'http://127.0.0.1:3002',feishu:'https://open.feishu.cn/open-apis/bot/v2/hook/',wecom:'https://qyapi.weixin.qq.com/cgi-bin/webhook/send'};
const nativeStyle=document.createElement('style');nativeStyle.textContent='.native-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:16px}.native-card{background:white;border:1px solid #e4e6f0;border-top:4px solid var(--accent,#8065df);border-radius:14px;padding:20px}.native-card h3{font-size:15px;margin-bottom:14px}.native-card input:not([type=checkbox]),.native-card select{width:100%;box-sizing:border-box}.native-card label{font-size:12px;color:#68748f}.native-card .btn{margin-top:10px}.native-fields{display:grid;grid-template-columns:1fr 1fr;gap:9px}.native-meta{color:#7a86a0;font-size:12px;line-height:1.8;margin:12px 0}.native-list{display:flex;align-items:center;justify-content:space-between;padding:12px 0;border-bottom:1px solid #eff0f6;gap:15px}.native-chart{width:100%;height:170px}.native-tools{display:flex;flex-wrap:wrap;gap:5px;margin:10px 0}';document.head.appendChild(nativeStyle);
const monitorKeywordStyle=document.createElement('style');monitorKeywordStyle.textContent='.monitor-keyword-panel{margin-bottom:18px}.monitor-keyword-rule{padding:18px 0;border-top:1px solid #edf0f6}.monitor-keyword-rule:first-of-type{border-top:0}.monitor-keyword-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.monitor-keyword-chips{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.monitor-keyword-chip{display:inline-flex;align-items:center;gap:7px;border:1px solid #dfe4ef;background:#f7f8fc;color:#29364b;border-radius:999px;padding:6px 8px 6px 12px;font-size:13px}.monitor-keyword-chip button{border:0;background:#e7eaf2;color:#596780;border-radius:50%;width:20px;height:20px;line-height:18px;cursor:pointer}.monitor-keyword-chip button:hover{background:#fee8e8;color:#b42332}.monitor-keyword-add{display:flex;gap:8px;max-width:560px}.monitor-keyword-add input{flex:1;min-width:0;border:1px solid #dce2ef;border-radius:9px;padding:10px 12px}.monitor-keyword-add .btn{white-space:nowrap}.monitor-keyword-rule .native-meta{margin:8px 0}.monitor-keyword-empty{padding:18px;border:1px dashed #cfd7e5;border-radius:10px;color:#64718a;background:#fafbfe}';document.head.appendChild(monitorKeywordStyle);
const acquisitionStyle=document.createElement('style');acquisitionStyle.textContent='.acq-summary{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}.acq-count{border:1px solid #e4e8f1;background:#fff;border-radius:11px;padding:10px 14px;min-width:112px}.acq-count b{display:block;color:#202a3d;font-size:19px;margin-top:3px}.acq-count span{color:#64718a;font-size:12px}.acq-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:16px 0}.acq-filter{border:1px solid #dce2ee;background:#fff;color:#46536b;border-radius:999px;padding:7px 13px;font-size:13px;cursor:pointer}.acq-filter:hover,.acq-filter.on{border-color:#7660dc;background:#f2efff;color:#503ab8}.acq-list{display:grid;gap:10px}.acq-record{display:grid;grid-template-columns:175px minmax(250px,1.6fr) minmax(150px,.9fr) minmax(90px,.45fr);gap:16px;align-items:center;padding:16px 18px;border:1px solid #e4e8f0;border-left:4px solid #2eaa78;background:#fff;border-radius:12px;box-shadow:0 2px 7px rgba(31,47,78,.035)}.acq-record.failed{border-left-color:#d94e5c;background:linear-gradient(90deg,#fffafa,#fff 22%)}.acq-record.saved{border-left-color:#7b63d9}.acq-time{color:#263249;font-size:13px;font-weight:650}.acq-time small,.acq-source small,.acq-related small{display:block;color:#64718a;font-size:11px;font-weight:400;margin-top:5px}.acq-source{min-width:0;color:#202a3d;font-weight:700;font-size:14px}.acq-source-line{display:flex;align-items:center;flex-wrap:wrap;gap:7px}.acq-tag{display:inline-flex;align-items:center;border-radius:6px;background:#eff2f7;color:#46536b;padding:4px 8px;font-size:11px;font-weight:650}.acq-detail{color:#3d4960;font-size:13px;line-height:1.55;margin-top:7px;overflow-wrap:anywhere}.acq-related{font-size:12px;color:#3f4c63}.acq-related .wf-link{font-size:12px;overflow-wrap:anywhere}.acq-status{display:inline-flex;justify-content:center;min-width:62px;padding:6px 9px;border-radius:7px;font-size:12px;font-weight:700}.acq-status.ok{background:#e7f7ef;color:#14764b}.acq-status.bad{background:#fff0f0;color:#bd303b}.acq-status.neutral{background:#f0edff;color:#6147bb}.acq-id{margin-top:7px;color:#64718a;font-size:11px}.acq-id summary{cursor:pointer}.acq-id code{display:block;color:#33415a;overflow-wrap:anywhere;margin-top:4px}.acq-empty{padding:34px;text-align:center;color:#586780;background:#fff;border:1px dashed #cfd7e5;border-radius:12px}@media(max-width:900px){.acq-record{grid-template-columns:1fr 1fr;align-items:start}.acq-source{grid-column:1/-1}.acq-related{grid-column:1/-1}}@media(max-width:560px){.acq-record{grid-template-columns:1fr}.acq-source,.acq-related{grid-column:auto}}';document.head.appendChild(acquisitionStyle);
async function nativeSync(){const [routes,services,agents,templates,sources,dashboard,approvals,sentiment,sampling,signals]=await Promise.all(['/config/llm','/config/services','/agents','/templates','/hotlists/sources','/dashboard','/approvals','/config/sentiment','/config/sampling','/signals'].map(p=>liveApi(p)));Object.assign(native,{routes,services,agents,templates,sources,dashboard,approvals,sentiment,sampling,signals});}
const nativePreviousSync=liveSync;liveSync=async function(){await nativePreviousSync();await nativeSync();};
function nativeHead(id,title,subtitle){return v4ConfigNav(id)+wfHead(title,subtitle);}
function nativeLLM(){document.getElementById('p-llm').innerHTML=nativeHead('llm','LLM 模型与路由','原七个业务槽保留；新增对话与编排槽。配置不代表供应商已实测。')+`<div class="wf-note">只保存真实配置，不预填不存在的模型 ID。Key 留空表示保留已保存凭据。研究槽需填写准确费率才能通过预算预留；对话槽可先联通，未填费率则费用保持未知。价格单位：元 / 百万 Token。关键词与话题槽先保留配置。<button class="btn" onclick="nativeSeedResearchRoutes()">用对话模型填充空白研究槽</button></div><div class="native-grid">${native.routes.map((r,i)=>`<form class="native-card" data-native-route="${r.id}" style="--accent:${v4Colors[i%8]}"><h3>${liveEsc(nativeLabels[r.id])} ${v4Tag(r.key_configured?'已保存凭据':'未配置凭据',r.key_configured?'g':'gr')}</h3><div class="v4-field"><label>API 协议</label><select name="protocol"><option value="openai-completions" ${r.protocol!=='anthropic-messages'?'selected':''}>OpenAI 兼容</option><option value="anthropic-messages" ${r.protocol==='anthropic-messages'?'selected':''}>Anthropic Messages</option></select></div><div class="v4-field"><label>供应商名称</label><input name="provider" value="${liveEsc(r.provider)}" placeholder="DeepSeek / LiteLLM / 自有代理" required></div><div class="v4-field"><label>API Base URL（Anthropic 地址填到 /api/anthropic）</label><input name="base_url" type="url" value="${liveEsc(r.base_url)}" placeholder="https://api.example.com/v1 或 /api/anthropic" required></div><div class="v4-field"><label>实际模型 ID</label><input name="model" value="${liveEsc(r.model)}" required></div><div class="v4-field"><label>API Key（仅写入服务器，保存后不回传）</label><input name="api_key" type="password" autocomplete="new-password" placeholder="留空保留已保存凭据"></div><div class="native-fields"><div><label>每次最大输出 Token</label><input name="max_tokens" type="number" min="256" max="65536" value="${r.max_tokens||8192}"></div><label><input name="enabled" type="checkbox" ${r.enabled?'checked':''}> 启用此路由</label></div><details class="native-meta"><summary>可选计费单价</summary><div class="native-fields">${['input','cache','output'].map(k=>`<label>${{input:'非缓存输入',cache:'缓存命中',output:'输出'}[k]}<input name="price_${k}" type="number" step="any" min="0" value="${r.rates?.[k]??''}"></label>`).join('')}</div></details><button class="btn dark" type="submit">保存模型配置</button></form>`).join('')}</div>`;}
async function nativeSeedResearchRoutes(){try{const r=await liveApi('/config/llm/seed-research-from-chat','POST',{});await nativeSync();nativeLLM();showToast(`已填充空白研究槽：${r.created.join('、')||'没有空白槽'}；请逐槽填写计费单价后再开启研判`);}catch(e){liveError(e);}}
v4RenderKeys=function(){document.getElementById('p-keys').innerHTML=nativeHead('keys','Key 与服务配置','密钥由本机后端加密保存，不写入 HTML 或浏览器存储')+`<div class="wf-note">模型和角色映射统一在 <button class="btn" onclick="v4Go('llm')">LLM 模型与路由</button> 管理。这里保存检索、抓取和通知服务凭据。通知不会因为保存 Key 自动发送；还需要明确订阅与启用策略。</div><div class="native-grid">${native.services.map((r,i)=>`<form class="native-card" data-native-service="${r.id}" style="--accent:${v4Colors[i%8]}"><h3>${liveEsc(r.id)} ${v4Tag(r.key_configured?'凭据已保存':'待配置',r.key_configured?'g':'gr')}</h3><div class="v4-field"><label>服务端点 / Base URL</label><input name="base_url" type="url" value="${liveEsc(r.base_url||nativeDefaults[r.id]||'')}" required></div><div class="v4-field"><label>Key / Webhook 凭据（保存后不回传）</label><input name="api_key" type="password" autocomplete="new-password" placeholder="留空保留原凭据"></div><label><input name="enabled" type="checkbox" ${r.enabled?'checked':''}> 允许本项目使用</label><p class="native-meta">${['tavily','bocha','anspire'].includes(r.id)?'研究检索会使用已启用的供应商，重复链接归并，搜索摘要不作为原文证据。':['feishu','wecom'].includes(r.id)?'只保存连接信息；发送由通知订阅决定。':'配置可保存，具体供应商执行支持见信源页。'}</p><button class="btn dark">保存服务配置</button>${r.id==='wecom'?`<button class="btn" type="button" data-test-notification="wecom" ${r.key_configured&&r.enabled?'':'disabled'}>发送测试消息</button><span class="native-meta">通道状态：${liveEsc(r.health?.status||'未测试')}</span>`:''}</form>`).join('')}</div><div class="wf-note">热榜已改为后端内部采集函数，无需再配置 NewsNow :3000 或 DailyHotApi :6688 地址。主密钥位于本机 data 目录，备份需与数据库一并保留。</div>`;};
function nativeSentimentPanel(){const s=native.sentiment||{};return `<section class="native-card" style="--accent:#0f9692;margin:20px 0"><h3>独立情感模型层</h3>${v4Tag(s.enabled?'本地 ONNX 推理':'尚未启用',s.enabled?'g':'gr')} ${v4Tag(s.installed?'模型文件已安装':'等待模型文件',s.installed?'g':'gr')}<p class="native-meta">BettaFish 默认多语言五级分类器：${liveEsc(s.model_id||'tabularisai/multilingual-sentiment-analysis')}。在本机运行，不占用 LLM 槽、API Key 或云端 Token。</p><p class="native-meta">输出：非常负面 / 负面 / 中性 / 正面 / 非常正面。每条仅分析前 512 个分词 Token；置信度是模型分数，不是正确率。低置信度保留未知。</p><form data-local-sentiment><label><input name="enabled" type="checkbox" ${s.enabled?'checked':''} ${s.installed?'':'disabled'}> 新研究启用独立情感模型</label><div class="v4-field"><label>置信度阈值</label><input type="number" name="min_confidence" min="0" max="1" step="0.05" value="${s.min_confidence??0.5}"></div><button class="btn dark">保存</button> <button class="btn" type="button" onclick="nativeSentimentTest()" ${s.installed?'':'disabled'}>运行本地测试</button></form><div id="native-sentiment-result" class="native-meta"></div></section>`;}
async function nativeSentimentTest(){try{const r=await liveApi('/config/sentiment/test','POST',{});document.getElementById('native-sentiment-result').innerHTML=r.results.map(v=>`<p>${liveEsc(v.text)} → ${liveEsc(({very_negative:'非常负面',negative:'负面',neutral:'中性',positive:'正面',very_positive:'非常正面'})[v.label]||v.label)} · 置信度 ${(v.confidence*100).toFixed(1)}%</p>`).join('');}catch(e){liveError(e);}}
document.addEventListener('submit',async e=>{if(!e.target.matches('[data-local-sentiment]'))return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await liveApi('/config/sentiment','PUT',{enabled:!!d.enabled,min_confidence:Number(d.min_confidence)});await nativeSync();nativeAgents();showToast('已保存；已开始的任务沿用原配置');}catch(error){liveError(error);}});
function nativeAgents(){document.getElementById('p-agent').innerHTML=nativeHead('agent','Agent 与引擎','dsh 原生成员；调用状态以具体研究任务中的子会话为准')+`<div class="wf-note">Insight / Media / Query 并行调查，ForumHost 整理分歧，Planner / Verifier / Advocate 分别审查，Report 完整成稿。当前配置与真实运行、真实报告质量分别验收。</div>${nativeSentimentPanel()}${nativeSamplingPanel()}<div class="native-grid">${native.agents.map((a,i)=>`<section class="native-card" style="--accent:${v4Colors[i%8]}"><h3>${liveEsc(a.name)}</h3>${v4Tag(a.configured?'模型路由已配置':'等待模型路由',a.configured?'g':'gr')}<div class="native-meta">底座：dsh 原生子 Agent<br>独立子会话、工具白名单、结构化成果；角色 ${liveEsc(a.id)}</div><div class="native-tools">${a.tools.map(t=>v4Tag(t,'gr')).join('')}</div><button class="btn" onclick="v4Go('llm')">配置模型路由</button></section>`).join('')}</div>`;}
wfSources=function(){const rows=native.sources?.configured||[];document.getElementById('p-src').innerHTML=wfHead('信源 · 数据渠道与健康','热榜和研究取证共用的渠道目录；具体原文在任务证据里')+`<div class="wf-note">显示实际采集结果，不把“已配置”当成“连接正常”。热榜模块直接访问原始平台，不依赖独立热榜服务。</div><div class="wf-panel"><table class="wf-table"><thead><tr><th>渠道</th><th>实现来源</th><th>最近状态</th><th>取得时间</th></tr></thead><tbody>${rows.map(s=>{const last=native.sources.latest.find(x=>x.provider===s.provider&&x.source_id===s.source_id);return `<tr><td>${liveEsc(s.title)}<small>${liveEsc(s.origin)}</small></td><td>${liveEsc(s.provider)} · 内部模块</td><td>${v4Tag(last?last.status==='succeeded'?'最近采集成功':'最近采集失败':'尚未采集',last?.status==='succeeded'?'g':'gr')}</td><td>${last?liveEsc(liveStamp(last.observed_at)):'—'}</td></tr>`;}).join('')}${native.services.map(s=>`<tr><td>${liveEsc(s.id)}</td><td>${s.enabled?'配置允许使用':'未启用'}</td><td>${s.key_configured?'凭据已保存，未据此声称实测':'未配置'}</td><td><button class="btn" onclick="v4Go('keys')">配置</button></td></tr>`).join('')}</tbody></table></div>`;};
const acquisitionSourceNames={ 'newsnow:zhihu':'知乎热榜','newsnow:baidu':'百度实时热点','dailyhot:weibo':'微博热搜','dailyhot:bilibili':'哔哩哔哩全站榜' },acquisitionOperationNames={native_snapshot:'热榜快照',user_import:'用户导入原文',web_search:'网页检索',scrape:'网页抓取',deep_crawl:'深度采集'};
function nativeRecordFilter(value){native.recordFilter=value;wfRecords();}
wfRecords=function(){const all=(wf.records||[]).filter(r=>(!wf.recordTask||r.task===wf.recordTask)&&(!wf.recordSource||r.source===wf.recordSource)),rows=all.filter(r=>native.recordFilter==='all'||(native.recordFilter==='failed'?['failed','失败'].includes(r.status):native.recordFilter==='success'?['succeeded','成功'].includes(r.status):['已保存','saved','user_import'].includes(r.status)||r.operation==='user_import')),failed=all.filter(r=>['failed','失败'].includes(r.status)).length,succeeded=all.filter(r=>['succeeded','成功'].includes(r.status)).length,saved=all.length-failed-succeeded;const status=r=>['failed','失败'].includes(r.status)?['失败','failed','bad']:['succeeded','成功'].includes(r.status)?['采集成功','ok','ok']:['已保存','saved','user_import'].includes(r.status)||r.operation==='user_import'?['已归档','saved','neutral']:[r.status||'未知','saved','neutral'];const head=wfHead('采集流水 · 执行记录','按一次实际执行记录展示来源、结果和说明；可从任务或来源追溯',`<button class="btn" onclick="wf.recordTask=null;wf.recordSource=null;native.recordFilter='all';wfRecords()">重置筛选</button>`);document.getElementById('p-crawl').innerHTML=`${head}<div class="wf-note">${wf.recordTask?`当前任务：${liveEsc(wf.recordTask)} · `:''}${wf.recordSource?`当前来源：${liveEsc(wf.recordSource)} · `:''}只有真实获取、失败或用户归档时才生成记录；普通问答和阅读报告不会触发采集。完整记录编号可展开查看。</div><div class="acq-summary"><div class="acq-count"><span>当前记录</span><b>${all.length}</b></div><div class="acq-count"><span>采集成功</span><b style="color:#14764b">${succeeded}</b></div><div class="acq-count"><span>采集失败</span><b style="color:#bd303b">${failed}</b></div><div class="acq-count"><span>归档 / 其他</span><b>${saved}</b></div></div><div class="acq-toolbar" role="group" aria-label="筛选采集记录">${[['all','全部'],['success','成功'],['failed','失败'],['saved','归档']].map(([k,label])=>`<button class="acq-filter ${native.recordFilter===k?'on':''}" aria-pressed="${native.recordFilter===k}" onclick="nativeRecordFilter('${k}')">${label}${k==='all'?` ${all.length}`:k==='failed'?` ${failed}`:k==='success'?` ${succeeded}`:''}</button>`).join('')}</div><div class="acq-list">${rows.map(r=>{const [state,cls,badge]=status(r),source=String(r.source||'未知来源'),sourceTitle=acquisitionSourceNames[source]||source,operation=acquisitionOperationNames[r.operation]||r.operation||'执行';return `<article class="acq-record ${cls}"><div class="acq-time">${liveEsc(r.time||'时间未知')}<details class="acq-id"><summary>记录编号</summary><code>${liveEsc(r.id)}</code></details></div><div class="acq-source"><div class="acq-source-line"><span>${liveEsc(sourceTitle)}</span><span class="acq-tag">${liveEsc(source)}</span><span class="acq-tag">${liveEsc(operation)}</span></div><div class="acq-detail">${liveEsc(r.detail||'暂无补充说明')}</div></div><div class="acq-related">${r.task?`关联任务<button class="wf-link" onclick="wfOpenTask('${liveEsc(r.task)}')">${liveEsc(r.task)}</button>`:'监测 / 全局采集'}</div><div><span class="acq-status ${badge}">${liveEsc(state)}</span></div></article>`;}).join('')||`<div class="acq-empty">${all.length?'当前筛选条件下没有记录。':'暂无采集记录。执行一次榜单采集、任务取证或归档操作后，记录会出现在这里。'}</div>`}</div>`;};
function nativeExtensions(id){const kind=id==='skill'?'skills':id;liveApi('/config/extensions/'+kind).then(data=>{document.getElementById('p-'+id).innerHTML=nativeHead(id,{mcp:'MCP 服务',skill:'Skill 技能',tools:'Tool 工具'}[id],'保存配置与实际挂载分别显示')+`<div class="wf-note">${liveEsc(data.note)}。当前内置研究工具由代码注册，不能通过编辑 JSON 获得额外权限。</div><form data-native-extensions="${kind}" class="v4-panel"><label>扩展条目 JSON（id、name、description、enabled）</label><textarea name="items" style="width:100%;min-height:280px;font:13px monospace">${liveEsc(JSON.stringify(data.items,null,2))}</textarea><button class="btn dark">保存扩展清单</button></form>`;}).catch(liveError);}
function nativeTemplates(filter='all'){const origins={bettafish_builtin:'BettaFish 内置',user_import:'用户上传',co_created:'人机共创','diting-authored':'历史自有骨架'};const items=native.templates.filter(t=>filter==='all'||t.origin===filter);document.getElementById('p-tpl').innerHTML=wfHead('模板中心','三种模板来源；用户指定优先，未指定时按研究主题自动选型',`<button class="btn" onclick="wfCompose('请与我共创一份报告模板，先讨论读者、主题和章节结构，暂不启动研究')">人机共创模板</button> <button class="btn dark" onclick="nativeUploadTemplate()">上传 Markdown 模板</button>`)+`<div class="native-template-tabs" style="display:flex;gap:10px;margin:18px 0;flex-wrap:wrap">${[['all','全部模板'],['bettafish_builtin','BettaFish 内置'],['user_import','用户上传'],['co_created','人机共创']].map(([id,label])=>`<button class="btn ${filter===id?'dark':''}" onclick="nativeTemplates('${id}')">${label}</button>`).join('')}</div><div class="native-grid">${items.map((t,i)=>`<section class="native-card" style="--accent:${v4Colors[i%8]}"><h3>${liveEsc(t.name)}</h3>${v4Tag(origins[t.origin]||'历史模板','g')}<p class="native-meta">${liveEsc(t.focus||'沿用已保存章节要求组织研究；可在对话中继续讨论模板。')}</p><ol class="native-meta">${(t.main_sections||t.sections).map(s=>`<li>${liveEsc(s)}</li>`).join('')}</ol><p class="native-meta">正文以中文分析和章节图表为主，溯源与统计方法置于附录。</p><button class="btn" onclick="nativeUseTemplate('${liveEsc(t.id)}')">在对话中使用</button> <button class="btn" onclick="nativePreviewTemplate('${liveEsc(t.id)}')">查看完整骨架</button></section>`).join('')||'<p class="native-meta">这里还没有模板。上传文件，或在对话中共创后确认保存。</p>'}</div>`;}
function nativeUseTemplate(id){const t=native.templates.find(t=>t.id===id);if(t)wfCompose('请采用「'+t.name+'」模板进行深度研判，研究主题：');}
function nativePreviewTemplate(id){const t=native.templates.find(t=>t.id===id);if(t)v4Modal(t.name,`<p class="native-meta">已保存模板；生成报告时冻结此版本。</p><pre style="white-space:pre-wrap;font-size:14px;line-height:1.9;max-height:65vh;overflow:auto">${liveEsc(t.markdown||t.sections.join('\n'))}</pre>`);}

function nativeUploadTemplate(){v4Modal('上传或创建报告骨架',`<form data-native-template><input type="hidden" name="origin" value="user_import"><div class="v4-field"><label>模板名称</label><input name="name" required maxlength="100"></div><div class="v4-field"><label>Markdown 文件（可选）</label><input name="file" type="file" accept=".md,text/markdown"></div><div class="v4-field"><label>或粘贴 Markdown 骨架</label><textarea name="markdown" rows="12" placeholder="# 报告标题&#10;## 报告摘要&#10;## 背景与演变&#10;## 多方观点&#10;## 影响分析&#10;## 风险研判&#10;## 结论与建议"></textarea></div><p class="native-meta">报告骨架不会执行代码或提高工具权限；报告仍需真实证据和质量审查。</p><button class="btn dark">保存模板</button></form>`);}
wfApprovals=function(){document.getElementById('p-approve').innerHTML=nativeHead('approve','审批中心','仅显示真实执行请求；批准只覆盖列出的具体范围')+`<div class="wf-panel">${native.approvals.length?native.approvals.map(a=>`<div class="native-list"><div><b>${liveEsc(a.operation)}</b><p class="native-meta">任务 ${liveEsc(a.task_id)} · ${liveEsc(a.status)}<br>${liveEsc(a.request_json)}</p></div>${a.status==='pending'?`<div><button class="btn" onclick="nativeDecide('${a.id}',false)">拒绝</button><button class="btn dark" onclick="nativeDecide('${a.id}',true)">批准此范围</button></div>`:''}</div>`).join(''):'<div class="wf-empty">没有待审批的真实操作。</div>'}</div>`;};
async function nativeDecide(id,approved){try{await liveApi('/approvals/'+id+'/decision','POST',{approved});await nativeSync();wfApprovals();showToast(approved?'审批已记录，任务将继续':'已拒绝，未执行操作');}catch(e){liveError(e);}}
const nativeOriginalGo=v4Go;v4Go=function(id){nativeOriginalGo(id);if(id==='llm')nativeLLM();if(id==='agent')nativeAgents();if(id==='src')wfSources();if(id==='tpl')nativeTemplates();if(['mcp','skill','tools'].includes(id))nativeExtensions(id);if(id==='sigs')nativeSignals();document.querySelectorAll('.live-config-note').forEach(n=>n.remove());};
function nativeKeywordPanel(){const monitors=native.monitors||[];return `<section class="wf-panel monitor-keyword-panel"><div class="wf-between"><div><h3>我的值守关键词</h3><p class="native-meta">在这里直接添加或移除关注词。保存后用于后续监测巡检，不会立即采集，也不会自动启动研判。</p></div><button class="btn" onclick="v4Go('hot');wfHotTab('监测订阅')">监测规则设置</button></div>${monitors.map(m=>`<div class="monitor-keyword-rule"><div class="monitor-keyword-heading"><b>${liveEsc(m.title)}</b>${v4Tag(m.enabled?'值守中':'已停用',m.enabled?'g':'gr')}<span class="native-meta">${liveEsc(m.cron||`${m.interval_minutes} 分钟巡检`)} · ${m.rule==='keyword_growth'?'关键词 + 热度增长':'关键词命中'} · ${m.action==='confirm'?'命中待确认':'命中只提醒'}</span></div><div class="monitor-keyword-chips" aria-label="${liveEsc(m.title)}关键词">${m.keywords.map(k=>`<span class="monitor-keyword-chip"><span>${liveEsc(k)}</span><button type="button" aria-label="移除关键词 ${liveEsc(k)}" title="移除 ${liveEsc(k)}" data-monitor-keyword-remove="${liveEsc(m.id)}" data-keyword="${liveEsc(k)}">×</button></span>`).join('')}</div><form class="monitor-keyword-add" data-monitor-keyword-add="${liveEsc(m.id)}"><label class="sr-only" for="monitor-keyword-${liveEsc(m.id)}">添加关注关键词</label><input id="monitor-keyword-${liveEsc(m.id)}" name="keyword" maxlength="80" placeholder="输入一个想关注的关键词" required><button class="btn dark" type="submit">添加关键词</button></form><p class="native-meta">${m.keywords.length}/30 个关键词 · 修改只影响后续巡检，历史信号和采集记录不会重写。</p></div>`).join('')||`<div class="monitor-keyword-empty">目前还没有监测规则。先到热点追踪创建规则，再回来管理关键词。</div>`}</section>`;}
function nativeSignals(){const current=native.signals.filter(s=>!s.historical_archive),historical=native.signals.filter(s=>s.historical_archive),card=s=>`<div class="native-list"><div><b>${liveEsc(s.title)}</b><p class="native-meta">${liveEsc(s.reason)}</p>${s.historical_archive?'<p class="native-meta">历史归档命中：原文在监测规则建立前已归档，不属于新捕捉线索。</p>':''}</div>${s.task_id?`<button class="btn" onclick="wfOpenTask('${s.task_id}')">关联任务</button>`:`<button class="btn" onclick="wfCompose(${liveEsc(JSON.stringify(s.title))})">在对话中调查</button>`}</div>`;document.getElementById('p-sigs').innerHTML=wfHead('信号','按实际监测规则产生；风险线索不等于事实指控')+nativeKeywordPanel()+`<div class="wf-panel"><div class="wf-between"><h3>监测信号</h3><span class="native-meta">新线索 ${current.length} 条</span></div>${current.map(card).join('')||'<div class="wf-empty">目前没有新线索。规则建立前已经归档的材料不会作为新发现重复提醒。</div>'}${historical.length?`<details class="monitor-keyword-rule"><summary>历史归档命中 ${historical.length} 条（不计入新线索）</summary>${historical.map(card).join('')}</details>`:''}</div>`;}
function nativeMonitorInput(m,keywords){return {title:m.title,keywords,enabled:!!m.enabled,interval_minutes:[5,15,30,60].includes(Number(m.interval_minutes))?Number(m.interval_minutes):15,...(m.cron?{cron:m.cron}:{}),rule:m.rule==='keyword'?'keyword':'keyword_growth',growth:Number(m.growth)||2,action:m.action==='confirm'?'confirm':'notify',auto_research:false,budget:Number(m.budget)||20,max_daily_tasks:Number(m.max_daily_tasks??3),daily_budget:Number(m.daily_budget??60)};}
async function nativeSaveMonitorKeywords(id,keywords){const monitor=(native.monitors||[]).find(m=>m.id===id);if(!monitor)throw Error('监测规则已不存在，请刷新页面');const cleaned=[...new Map(keywords.map(k=>[k.normalize('NFKC').toLocaleLowerCase().replace(/\s+/g,' ').trim(),k.trim()])).values()].filter(Boolean);if(!cleaned.length)throw Error('至少保留一个关键词');if(cleaned.length>30)throw Error('每条监测规则最多 30 个关键词');await liveApi('/monitors/'+encodeURIComponent(id),'PUT',nativeMonitorInput(monitor,cleaned));await nativeSync();nativeSignals();}
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-monitor-keyword-add]');if(!form)return;e.preventDefault();const id=form.dataset.monitorKeywordAdd,keyword=new FormData(form).get('keyword')?.toString().trim();if(!keyword)return;const monitor=(native.monitors||[]).find(m=>m.id===id);if(!monitor)return liveError(new Error('监测规则已不存在，请刷新页面'));const normalized=keyword.normalize('NFKC').toLocaleLowerCase().replace(/\s+/g,' ').trim();if(monitor.keywords.some(k=>k.normalize('NFKC').toLocaleLowerCase().replace(/\s+/g,' ').trim()===normalized)){showToast('这个关键词已存在');return;}try{await nativeSaveMonitorKeywords(id,[...monitor.keywords,keyword]);showToast(`已添加关注词：${keyword}`);}catch(error){liveError(error);}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-monitor-keyword-remove]');if(!button)return;const {monitorKeywordRemove:id,keyword}=button.dataset,monitor=(native.monitors||[]).find(m=>m.id===id);if(!monitor)return liveError(new Error('监测规则已不存在，请刷新页面'));if(monitor.keywords.length<=1)return showToast('监测规则至少需要保留一个关键词');try{await nativeSaveMonitorKeywords(id,monitor.keywords.filter(k=>k!==keyword));showToast(`已移除关注词：${keyword}`);}catch(error){liveError(error);}});
const nativeOriginalChat=v4RenderChat;v4RenderChat=function(){nativeOriginalChat();const route=native.routes.find(r=>r.id==='chat');const selector=document.querySelector('#p-chat [aria-label="对话模型"]');if(selector){selector.innerHTML=`<option>${liveEsc(route?.enabled?route.model:'尚未配置对话模型')}</option>`;selector.disabled=true;selector.title='在定制中心配置真实问答路由';}const note=document.querySelector('#p-chat .v4-note');if(note)note.textContent='普通问答使用已配置的对话模型；明确研究需求创建独立任务；报告追问绑定已归档版本，不自动重新采集。';document.querySelectorAll('#p-chat .v4-label').forEach(n=>{if(n.textContent.includes('演示模式'))n.textContent='模型真实回传用量计入账本；页面估算不作为账单。';});};
liveBanner=function(){const cap=live.capabilities;document.querySelector('.v4-status-strip').innerHTML='<span class="v4-badge">TypeScript 持久任务版</span><span>'+liveEsc(cap?.ready?'dsh 执行条件就绪，真实研究仍按门禁验收':cap?.reason||'正在读取执行条件')+'</span><button class="btn" onclick="v4Go(\'chat\')">打开对话</button>';};
v4TokenSummary=function(){const u=live.usage;if(!u)return '<p>正在读取账本…</p>';return `<div class="wf-between"><h3>Token 与费用</h3><button class="btn" onclick="v4Go('usage')">完整账本</button></div><div class="native-fields">${[['输入',u.known_input],['输出',u.known_output],['输入中缓存命中',u.known_cache],['未知用量调用',u.unknown_usage_calls]].map(([label,value],i)=>`<div style="border-left:3px solid ${v4Colors[i]};padding:8px 12px"><small>${label}</small><h3>${Number(value).toLocaleString()}</h3></div>`).join('')}</div><p class="native-meta">已知费用 ${u.known_cost===null?'未知':'¥'+u.known_cost.toFixed(5)}；未知费用 ${u.unknown_cost_calls} 次。费率只使用你的配置，输入已包含缓存，不重复相加。</p>`;};
v4RenderUsage=function(){const u=live.usage;document.getElementById('p-usage').innerHTML=nativeHead('usage','Token 与费用','供应商回传账本；保留未知值')+`<div class="wf-panel">${v4TokenSummary()}</div><div class="wf-panel"><table class="wf-table"><thead><tr><th>时间 / 任务</th><th>角色 / 模型</th><th>输入</th><th>输出</th><th>缓存</th><th>费用</th></tr></thead><tbody>${(u?.calls||[]).map(c=>`<tr><td>${liveEsc(liveStamp(c.created_at))}<small>${liveEsc(c.task_id||'普通问答')}</small></td><td>${liveEsc(c.role)}<small>${liveEsc(c.model||c.provider)}</small></td><td>${c.input_tokens??'未知'}</td><td>${c.output_tokens??'未知'}</td><td>${c.cache_tokens??'未知'}</td><td>${c.cost===null?'未知':'¥'+c.cost.toFixed(5)}</td></tr>`).join('')}</tbody></table>${u?.calls.length?'':'<div class="wf-empty">还没有模型调用。</div>'}</div>`;};
rcExport=function(id){v4Modal('导出已入库报告',`<p>下载本报告固定版本；保留证据附录、统计表和图表。</p><div class="v4-report-actions">${['html','md','pdf'].map(f=>`<button class="btn dark" onclick="rcDownload('${id}','${f}')">下载 ${f.toUpperCase()}</button>`).join('')}</div>`);};
rcDownload=function(id,format){const a=document.createElement('a');a.href='/api/reports/'+encodeURIComponent(id)+'/export/'+format;a.download=(live.reports.find(r=>r.id===id)?.title||'报告')+'.'+format;a.click();};
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('[data-native-route],[data-native-service],[data-native-extensions],[data-native-template]'))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));try{if(f.dataset.nativeRoute){const input={id:f.dataset.nativeRoute,name:nativeLabels[f.dataset.nativeRoute],protocol:d.protocol,provider:d.provider,base_url:d.base_url,model:d.model,max_tokens:Number(d.max_tokens),enabled:!!d.enabled};if(d.api_key)input.api_key=d.api_key;if(['input','cache','output'].every(k=>d['price_'+k]!==''))input.rates=Object.fromEntries(['input','cache','output'].map(k=>[k,Number(d['price_'+k])]));await liveApi('/config/llm/'+input.id,'PUT',input);await nativeSync();nativeLLM();}else if(f.dataset.nativeService){const input={base_url:d.base_url,enabled:!!d.enabled};if(d.api_key)input.api_key=d.api_key;await liveApi('/config/services/'+f.dataset.nativeService,'PUT',input);await nativeSync();v4RenderKeys();}else if(f.dataset.nativeExtensions){await liveApi('/config/extensions/'+f.dataset.nativeExtensions,'PUT',{items:JSON.parse(d.items)});}else{const file=f.querySelector('[type=file]')?.files[0];if(file&&file.size>150000)throw Error('模板文件过大');const saved=await liveApi('/templates','POST',{name:d.name,markdown:file?await file.text():d.markdown,origin:d.origin||'user_import',...(d.session_id?{session_id:d.session_id}:{})});if(typeof window.ditingTemplateSelection!=='undefined')window.ditingTemplateSelection={mode:saved.origin==='co_created'?'co_created':'user_import',template_id:saved.id};v4CloseModal();await nativeSync();if(typeof window.renderTemplateSelection==='function')window.renderTemplateSelection();if(v4State.page==='tpl')nativeTemplates();}showToast('已保存到后端；密钥不回传浏览器');}catch(error){liveError(error);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-test-notification]');if(!b)return;b.disabled=true;try{const result=await liveApi('/config/services/'+b.dataset.testNotification+'/test','POST',{});showToast(result.detail||'通知测试成功');await nativeSync();v4RenderKeys();}catch(error){liveError(error);b.disabled=false;}});


// Persisted console behaviors layered over the v5 visual prototype.
const nativeOriginalChatRender=v4RenderChat;
v4RenderChat=function(){nativeOriginalChatRender();const s=v4Session(),messages=s?.messages||[],lastUser=messages.map((m,i)=>m.role==='user'?i:-1).filter(i=>i>=0).at(-1);if(lastUser===undefined||lastUser<0)return;const askedTemplate=/模板|报告骨架/.test(messages[lastUser]?.text||'');const assistant=messages.slice(lastUser+1).findLast(m=>m.role==='assistant');if(!askedTemplate||!assistant)return;const node=document.querySelector('.v4-chat-messages .v4-message:not(.user):last-child .v4-msg-content');if(node&&!node.querySelector('[data-save-chat-template]'))node.insertAdjacentHTML('beforeend','<div class="v4-report-actions"><button class="btn" data-save-chat-template onclick="nativeSaveChatTemplate()">保存这份骨架到模板中心</button></div>');};
function nativeSaveChatTemplate(){const messages=v4Session()?.messages||[],last=messages.findLast(m=>m.role==='assistant');if(!last)return;const markdown=String(last.text||'');v4Modal('保存对话生成的报告骨架',`<form data-native-template><input type="hidden" name="origin" value="co_created"><input type="hidden" name="session_id" value="${liveEsc(v4Session()?.id||'')}"><div class="v4-field"><label>模板名称</label><input name="name" required maxlength="100" value="对话共创骨架"></div><div class="v4-field"><label>Markdown 内容</label><textarea name="markdown" rows="16" required>${liveEsc(markdown)}</textarea></div><button class="btn dark">保存到模板中心</button></form>`);}
const nativeOriginalArchive=rcArchive;
rcArchive=async function(id){const current=live.reports.find(r=>r.id===id),archived=!!current?.archived;try{await liveApi('/reports/'+id+'/archive','POST',{archived:!archived});await liveSync();rcRender();showToast(archived?'报告已恢复到可交付列表':'报告已归档，报告文件与证据仍保留');}catch(e){liveError(e);}};
const nativeOriginalChatPage=v4RenderChat;
v4RenderChat=function(){nativeOriginalChatPage();const route=native.routes.find(r=>r.id==='chat'),p=document.getElementById('p-chat');if(!p)return;const note=p.querySelector('.v4-note');if(note)note.textContent=route?.key_configured&&route.enabled?`对话已连接 ${route.provider} · ${route.model}。普通问答直接调用模型；明确研究请求会创建独立任务。`:route?.key_configured?`模型凭据已保存，路由当前未启用；请到定制中心启用对话模型。`:'普通问答保留在此入口；配置并启用“对话”模型槽后即可调用真实模型。研究请求与一般问答分流。';const selector=p.querySelector('[aria-label="对话模型"]');if(selector){selector.disabled=true;selector.title=route?.key_configured?`${route.model} · 协议 ${route.protocol||'openai-completions'}`:'请先配置定制中心的对话模型槽';if(route?.model){const option=[...selector.options].find(o=>o.value.includes(route.model));if(option)selector.value=option.value;}}};
const chatEmptyStyle=document.createElement('style');chatEmptyStyle.textContent='.v4-chat-empty{max-width:660px;margin:auto;padding:34px 24px;text-align:center}.v4-chat-empty-mark{width:58px;height:58px;display:grid;place-items:center;margin:0 auto 16px;border-radius:18px;background:linear-gradient(145deg,#eee9ff,#f7eaf0);color:#7957d8;font-size:25px;box-shadow:0 8px 22px #6046a115}.v4-chat-empty h2{font-size:21px;color:#273247;margin:8px 0}.v4-chat-empty>p{font-size:13px;line-height:1.8;color:#748096;margin:0 auto 22px;max-width:470px}.v4-chat-empty-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;text-align:left}.v4-chat-empty-grid button{border:1px solid #e2e7f1;border-radius:11px;background:#fff;padding:13px 15px;color:#344158;cursor:pointer;box-shadow:0 2px 8px #26334c08;transition:.15s}.v4-chat-empty-grid button:hover{border-color:#c7b8f4;background:#faf8ff;transform:translateY(-1px)}.v4-chat-empty-grid b{display:block;font-size:12px;margin-bottom:4px}.v4-chat-empty-grid small{display:block;font-size:10px;line-height:1.55;color:#8590a4}.v4-chat-empty-note{margin-top:18px!important;font-size:10px!important;color:#969db0!important}@media(max-width:650px){.v4-chat-empty{padding:25px 8px}.v4-chat-empty-grid{grid-template-columns:1fr}}';document.head.appendChild(chatEmptyStyle);
const nativeChatEmptyRender=v4RenderChat;
function v4UseStarter(text){const field=document.querySelector('#p-chat .v4-chat-form textarea');if(!field)return;field.value=text;field.focus();field.dispatchEvent(new Event('input',{bubbles:true}));}
v4RenderChat=function(){nativeChatEmptyRender();const session=v4Session(),stream=document.querySelector('#p-chat .v4-chat-messages');if(!stream||session?.messages?.length)return;const linked=!!session.report;stream.innerHTML=`<section class="v4-chat-empty" aria-label="对话开始提示"><div class="v4-chat-empty-mark">${linked?'↗':'谛'}</div><div class="v4-label">${linked?'报告追问':'研究与问答'}</div><h2>${linked?'从报告结论继续追问':'今天想了解什么？'}</h2><p>${linked?'你可以追问结论依据、证据边界或建议；回答会限定在这份报告和已归档材料内。':'可以直接问基础问题，也可以提出一个研究主题。只有明确要求调查时，系统才创建独立研究任务。'}</p><div class="v4-chat-empty-grid">${(linked?[["解释核心判断","这份报告最重要的判断是什么？"],["查看证据边界","哪些结论证据最充分，哪些仍需核实？"],["追问风险建议","报告建议优先处理的风险是什么？"],["继续研究","基于这份报告，继续研究尚未解决的问题。"]]:[["问一个基础问题","舆情研判通常包含哪些步骤？"],["开始主题研究","请研究近期 AI 行业争议并形成可读报告。"],["了解数据口径","热榜排名能代表全网讨论声量吗？"],["查看系统用量","Token 输入、缓存命中和输出分别怎么计费？"]]).map(([label,prompt])=>`<button onclick="v4UseStarter(${liveEsc(JSON.stringify(prompt))})"><b>${liveEsc(label)}</b><small>${liveEsc(prompt)}</small></button>`).join('')}</div><p class="v4-chat-empty-note">选择示例只会填入输入框，不会自动发送、启动采集或创建任务。</p></section>`;};
const nativeOriginalBanner=liveBanner;
liveBanner=function(){nativeOriginalBanner();const status=document.querySelector('.v4-status-strip span:nth-child(2)');if(status)status.textContent='TypeScript 后端已连接 · 数据持久保存 · 模型与研究执行状态见定制中心';};

const nativeSyncConfiguration=nativeSync;nativeSync=async function(){await nativeSyncConfiguration();const [monitors,policy,subscription]=await Promise.all(['/monitors','/config/runtime','/subscriptions'].map(p=>liveApi(p)));Object.assign(native,{monitors,policy,subscription});for(const row of rcRows){const stored=live.reports.find(r=>r.id===row.id);if(stored?.archived)row.status='已归档';}};
function nativeSystem(){const p=native.policy||{enabled:false,max_calls:120,max_minutes:45};document.getElementById('p-conf').innerHTML=nativeHead('conf','系统配置','执行开关、任务限额与持久数据')+`<form class="native-card" data-native-policy><h3>研究执行策略</h3><label><input type="checkbox" name="enabled" ${p.enabled?'checked':''}> 启用真实模型研究（将消耗已配置供应商的额度）</label><div class="native-fields" style="margin-top:15px"><label>每任务模型调用上限<input type="number" name="max_calls" min="5" max="2000" value="${p.max_calls}"></label><label>单次连续执行上限（分钟）<input type="number" name="max_minutes" min="1" max="120" value="${p.max_minutes}"></label></div><p class="native-meta">每次模型调用前预留费用，三引擎共享本任务预算。缺少模型或费率时任务明确等待；修改全局模型配置不会覆盖已经冻结的任务模型配置。暂停恢复保留产物和账本，但会开启新的连续执行时段；分钟上限不等于整个任务的累计墙钟，任务仍共享预算和调用总上限。</p><button class="btn dark">保存执行策略</button></form><div class="native-card" style="margin-top:16px"><h3>调度与通知</h3><p class="native-meta">热点监测支持 5 / 15 / 30 / 60 分钟或 cron，默认不启用自动出报。通知只按你保存的订阅发送，报告先入库再通知。</p><button class="btn" onclick="v4Go('hot');wfHotTab('监测订阅')">管理热点监测</button><button class="btn" onclick="wfNotifications()">管理通知订阅</button></div>`;}
const nativeHotBoard=wfHotRender;wfHotRender=function(){if(wf.hot==='榜单'){nativeHotBoard();return;}document.getElementById('wf-hot-tabs').innerHTML=['榜单','预警线索','监测订阅'].map(t=>`<button class="${wf.hot===t?'on':''}" onclick="wfHotTab('${t}')">${t}</button>`).join('');const target=document.getElementById('wf-hot-body');if(wf.hot==='预警线索'){target.innerHTML=`<div class="wf-panel"><h3>真实监测线索</h3>${native.signals.length?native.signals.map(s=>`<div class="native-list"><div><b>${liveEsc(s.title)}</b><p class="native-meta">${liveEsc(s.reason)}</p></div><button class="btn" onclick="${s.task_id?`wfOpenTask('${s.task_id}')`:`wfCompose(${liveEsc(JSON.stringify(s.title))})`}">${s.task_id?'查看关联任务':'在对话中调查'}</button></div>`).join(''):'<div class="wf-empty">还没有符合已启用规则的信号。</div>'}</div>`;return;}target.innerHTML=`<div class="wf-panel"><div class="wf-between"><h3>监测规则与自动任务</h3><button class="btn dark" onclick="wfMonitorForm()">新增监测</button></div><div class="wf-note">只有启用的规则才会定时采集。可只产生线索，也可明确允许自动创建独立研究任务；不会覆盖用户对话任务。</div>${(native.monitors||[]).map(m=>`<div class="native-list"><div><b>${liveEsc(m.title)}</b> ${v4Tag(m.enabled?'已启用':'已停用',m.enabled?'g':'gr')}<p class="native-meta">${liveEsc(m.keywords.join('、'))} · ${liveEsc(m.cron||m.interval_minutes+' 分钟')} · ${m.rule==='keyword_growth'?'关键词 + 热度增长阈值':'关键词命中'}<br>${m.auto_research?'自动立题，单任务预算 ¥'+m.budget:'只产生线索，不自动出报'} · 下次 ${liveEsc(liveStamp(m.next_run_at))}</p></div><button class="btn" onclick="wfMonitorForm('${m.id}')">编辑规则</button></div>`).join('')||'<div class="wf-empty">尚未建立监测规则。</div>'}</div>`;};
wfMonitorForm=function(id){const m=(native.monitors||[]).find(m=>m.id===id)||{title:'',keywords:[],interval_minutes:15,rule:'keyword_growth',auto_research:false,budget:20,max_daily_tasks:3,daily_budget:60,enabled:false,growth:2};v4Modal(id?'编辑监测规则':'新增监测规则',`<form data-native-monitor="${id||''}"><div class="v4-field"><label>监测名称</label><input name="title" value="${liveEsc(m.title)}" required></div><div class="v4-field"><label>关键词（逗号分隔）</label><input name="keywords" value="${liveEsc(m.keywords.join(','))}" required></div><div class="native-fields"><label>采集间隔<select name="interval_minutes">${[5,15,30,60].map(n=>`<option ${n===m.interval_minutes?'selected':''}>${n}</option>`).join('')}</select></label><label>或 cron（北京时间）<input name="cron" value="${liveEsc(m.cron||'')}" placeholder="例如 */15 * * * *"></label><label>信号条件<select name="rule"><option value="keyword_growth" ${m.rule==='keyword_growth'?'selected':''}>关键词 + 同源指标增长</option><option value="keyword" ${m.rule==='keyword'?'selected':''}>关键词命中</option></select></label><label>增长阈值（%）<input name="growth" type="number" min="100" max="10000" value="${m.growth*100}"></label></div><div class="native-meta"><label><input type="checkbox" name="enabled" ${m.enabled?'checked':''}> 启用定时采集和巡检</label><br><label>命中后的处理<select name="action"><option value="notify" ${(m.action||(!m.auto_research?'notify':'auto'))==='notify'?'selected':''}>仅提醒：保存信号</option><option value="confirm" ${m.action==='confirm'?'selected':''}>待确认：用户确认后立题</option><option value="auto" ${m.auto_research?'selected':''}>自动研判：按预算排队出报</option></select></label></div><div class="native-fields"><label>单任务预算（元）<input name="budget" type="number" min="1" max="10000" value="${m.budget}"></label><label>全平台自动任务每日最多<input name="max_daily_tasks" type="number" min="0" max="20" value="${m.max_daily_tasks}"></label><label>全平台自动任务每日预算（元）<input name="daily_budget" type="number" min="0" max="10000" value="${m.daily_budget}"></label></div><p class="native-meta">排名不能换算成声量增长；没有可比正基准时不计算增长率。同一主题去重，先保存线索，再按额度判断是否立题。</p><button class="btn dark">保存监测规则</button></form>`);};
wfNotifications=function(){const s=native.subscription||{enabled:false,channels:[],events:['report.completed','approval.required','signal.created'],quiet:true};v4Modal('通知订阅与发送记录',`<form data-native-subscription><label><input type="checkbox" name="enabled" ${s.enabled?'checked':''}> 允许向以下渠道发送订阅事件</label><div class="native-meta">${[['feishu','飞书'],['wecom','企业微信']].map(([id,title])=>`<label style="margin-right:20px"><input name="channel_${id}" type="checkbox" ${s.channels.includes(id)?'checked':''}> ${title}</label>`).join('')}</div><div class="native-meta">${[['report.completed','报告入库完成'],['approval.required','需要审批'],['signal.created','新监测信号'],['task.attention_required','任务等待处理']].map(([id,title])=>`<label style="margin-right:15px"><input name="event_${id}" type="checkbox" ${s.events.includes(id)?'checked':''}> ${title}</label>`).join('')}</div><label><input name="quiet" type="checkbox" ${s.quiet?'checked':''}> 北京时间 22:00–08:00 暂缓发送</label><p class="native-meta">需先在 Key 与服务配置保存对应机器人的 Webhook。启用后只发送新的匹配事件，不补发此前历史消息；失败重试不会改变研究或报告状态。</p><button class="btn dark">保存通知订阅</button></form><h3 style="margin-top:20px">实际发送记录</h3>${wf.notifications.length?wf.notifications.map(n=>`<div class="native-list"><div>${liveEsc(n.time)} · ${liveEsc(n.channel)}<p class="native-meta">${liveEsc(n.title)}</p></div>${v4Tag(n.status,'gr')}</div>`).join(''):'<p class="native-meta">尚无通知事件。</p>'}`);};
rcSubscribe=wfNotifications;
const nativeGoWithConfig=v4Go;v4Go=function(id){nativeGoWithConfig(id);if(id==='conf')nativeSystem();if(id==='rules')document.getElementById('p-rules').innerHTML=nativeHead('rules','采集与研究守则','守则由代码执行；不是可一键跳过的提示词')+'<div class="native-grid">'+[['范围与权限','各角色只调用明确允许的工具；进一步关键词取证需批准具体范围。'],['真实数据','原文、引用、快照和底表保留出处与哈希；不把榜单当全网声量。'],['预算与判停','模型调用前预留费用，限制总调用和总时间；缺失 usage 仍保留费用预留。'],['质量与交付','结论必须引用本任务原文，三审绑定输入版本；变更证据使旧门禁失效。']].map(([h,p],i)=>`<div class="native-card" style="--accent:${v4Colors[i]}"><h3>${h}</h3><p class="native-meta">${p}</p></div>`).join('')+'</div>';};
const nativeTaskData=liveTask;liveTask=function(t,detail){const result=nativeTaskData(t,detail);result.remote=detail||t;return result;};
const nativeTaskDetail=wfDetail;wfDetail=function(){nativeTaskDetail();const t=wfTask(wf.task),agents=t?.remote?.agents||[];if(!t||!['过程','消费与日志'].includes(wf.tab))return;document.getElementById('p-tasks').insertAdjacentHTML('beforeend',`<div class="wf-panel"><h3>dsh 原生团队与门禁</h3>${agents.length?`<table class="wf-table"><thead><tr><th>角色</th><th>子会话</th><th>当前状态</th></tr></thead><tbody>${agents.map(a=>`<tr><td>${liveEsc(a.role)}</td><td><code>${liveEsc(a.child_session_id)}</code></td><td>${liveEsc(a.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="wf-empty">尚未启动原生研究成员。</div>'}${(t.remote.reviews||[]).map(r=>`<p>${v4Tag(r.gate,r.passed?'g':'gr')} ${r.passed?'通过':'未通过'} · ${liveEsc(r.reason)}</p>`).join('')}</div>`);};
wfEvidence=function(task,id){const e=wfTask(task)?.evidence.find(x=>x.id===id);if(e)v4Modal(task+' / '+id,`<h3>${liveEsc(e.title)}</h3><p>${liveEsc(e.source)}</p><blockquote class="wf-note">${liveEsc(e.quote)}</blockquote><p>来源类别：${e.origin==='user_import'?'用户导入原文；未声称联网核验':'网页正文归档；事实判断仍以任务审查为准'}</p>`);};
const nativeChatSession=liveSession;liveSession=function(s){const result=nativeChatSession(s);for(const m of result.messages)m.refs=[...new Set(m.text.match(/evidence_[a-f0-9]{32}/g)||[])];return result;};
v4ShowEvidence=async function(id){const s=v4Session(),tid=s.task||live.reports.find(r=>r.id===s.report)?.task_id;if(!tid)return showToast('此对话没有关联研究证据');try{const task=await liveApi('/tasks/'+tid),e=task.evidence.find(e=>e.id===id);if(!e)throw Error('此编号不属于当前任务已归档证据');v4Modal('原文证据 '+id,`<h3>${liveEsc(e.title)}</h3><a href="${liveEsc(e.source_url)}" target="_blank" rel="noopener noreferrer">${liveEsc(e.source_url)}</a><p class="native-meta">取得时间 ${liveEsc(liveStamp(e.captured_at))} · SHA-256 ${liveEsc(e.content_hash)}</p><blockquote class="wf-note">${liveEsc(e.content)}</blockquote>`);}catch(e){liveError(e);}};
wfChatCard=function(t){return `<div class="wf-chat-task"><div class="wf-between"><b>${liveEsc(t.id)}</b>${wfBadge(t.status)}</div><h4>${liveEsc(t.title)}</h4><p>${liveEsc(t.window)} · 预算 ¥${t.budget} · 独立持久任务</p><div class="wf-actions"><button class="btn" onclick="wfOpenTask('${t.id}')">查看任务</button>${t.status==='运行中'?`<button class="btn" onclick="wfAction('${t.id}','pause')">暂停</button>`:''}${t.report?`<button class="btn" onclick="rcRead('${t.report}')">阅读报告</button>`:''}</div></div>`;};
rcBody=function(r){return `<iframe title="完整报告正文、统计表与图表" src="/api/reports/${encodeURIComponent(r.id)}/export/html" sandbox="allow-same-origin allow-popups" style="width:100%;height:1100px;border:1px solid #e6e3f2;border-radius:12px;background:white"></iframe>`;};
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('[data-native-policy],[data-native-monitor],[data-native-subscription]'))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));try{if(f.hasAttribute('data-native-policy')){await liveApi('/config/runtime','PUT',{enabled:!!d.enabled,max_calls:Number(d.max_calls),max_minutes:Number(d.max_minutes)});await nativeSync();nativeSystem();}else if(f.hasAttribute('data-native-monitor')){const data={title:d.title,keywords:d.keywords.split(/[,，]/).map(s=>s.trim()).filter(Boolean),enabled:!!d.enabled,auto_research:d.action==='auto',action:d.action||'notify',interval_minutes:Number(d.interval_minutes),rule:d.rule,growth:Number(d.growth)/100,budget:Number(d.budget),max_daily_tasks:Number(d.max_daily_tasks),daily_budget:Number(d.daily_budget)};if(d.cron.trim())data.cron=d.cron.trim();const id=f.dataset.nativeMonitor;await liveApi('/monitors'+(id?'/'+id:''),id?'PUT':'POST',data);v4CloseModal();await nativeSync();wfHotRender();}else{await liveApi('/subscriptions','PUT',{enabled:!!d.enabled,channels:['feishu','wecom'].filter(c=>d['channel_'+c]),events:['report.completed','approval.required','signal.created','task.attention_required'].filter(k=>d['event_'+k]),quiet:!!d.quiet});v4CloseModal();await nativeSync();}showToast('已保存到后端');}catch(error){liveError(error);}});

const sourceDirectoryStyle=document.createElement('style');sourceDirectoryStyle.textContent='.src-overview{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:12px;margin:16px 0}.src-stat{background:#fff;border:1px solid #dfe5ef;border-radius:12px;padding:14px 16px}.src-stat span{display:block;color:#56647b;font-size:12px}.src-stat b{display:block;color:#192538;font-size:22px;margin-top:5px}.src-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:16px 0}.src-filter{border:1px solid #d6deea;background:#fff;color:#344258;border-radius:999px;padding:7px 13px;cursor:pointer}.src-filter.on{color:#fff;background:#302854;border-color:#302854}.src-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(275px,1fr));gap:12px}.src-card{background:#fff;border:1px solid #dce3ed;border-top:4px solid #8170d7;border-radius:12px;padding:15px 16px;box-shadow:0 2px 7px #182b4a0a}.src-card.failed{border-top-color:#c94350}.src-card.success{border-top-color:#178354}.src-card h3{font-size:15px;color:#172238;margin:0 0 5px}.src-url{font-size:11px;color:#56647b;overflow-wrap:anywhere}.src-meta{display:flex;flex-wrap:wrap;gap:6px;margin:11px 0}.src-pill{font-size:11px;color:#37445a;background:#edf1f7;border-radius:999px;padding:4px 8px}.src-state{display:inline-flex;border-radius:6px;padding:4px 8px;font-size:11px;font-weight:700;background:#edf0f5;color:#414d61}.src-state.ok{background:#e5f5ed;color:#126642}.src-state.bad{background:#fff0f0;color:#a92530}.src-state.pending{background:#fff6df;color:#795400}.src-detail{font-size:12px;color:#344258;line-height:1.55;margin-top:8px}.src-services{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:10px}.src-service{border:1px solid #dfe5ef;background:#fff;border-radius:10px;padding:13px}.src-section{margin:22px 0 10px;color:#1e2b40;font-size:16px}.src-note{color:#37445a;line-height:1.65}@media(max-width:700px){.src-overview{grid-template-columns:repeat(2,1fr)}}';document.head.appendChild(sourceDirectoryStyle);
function wfSourceFilter(kind){native.sourceFilter=kind;wfSources();}
wfSources=function(){const rows=native.sources?.configured||[],latest=native.sources?.latest||[],visible=rows.filter(s=>(native.sourceFilter||'all')==='all'||(native.sourceFilter==='hotlist'?s.kind==='hotlist':native.sourceFilter==='content'?s.kind==='content_rank':s.kind==='public_notice'||s.kind==='reference')),ok=rows.filter(s=>s.health==='succeeded').length,bad=rows.filter(s=>s.health==='failed').length,untested=rows.length-ok-bad,tag=s=>s.health==='succeeded'?['最近成功','ok']:s.health==='failed'?['最近失败','bad']:['尚未实测','pending'];const body=document.getElementById('p-src');if(!body)return;body.innerHTML=wfHead('信源 · 数据渠道与健康','展示渠道目录、数据类型和最近一次真实采集；具体每次执行及错误详情见采集流水')+`<div class="wf-note src-note"><b>信源回答“从哪里取、最近能不能取”；采集流水回答“某次执行具体发生了什么”。</b>当前目录共 ${rows.length} 个实际采集入口，覆盖 v5 原版 27 个展示频道并保留扩展信息源。展示频道与独立来源分别计数，内容榜和公共信息保留各自类型。只有点击采集或监测规则定时运行后，才会产生真实状态；尚未采集会如实标为未实测。平台指标保留原始口径，不跨平台比较。</div><div class="src-overview"><div class="src-stat"><span>已迁入目录</span><b>${rows.length}</b></div><div class="src-stat"><span>最近采集成功</span><b style="color:#126642">${ok}</b></div><div class="src-stat"><span>最近采集失败</span><b style="color:#a92530">${bad}</b></div><div class="src-stat"><span>尚未实测</span><b>${untested}</b></div></div><div class="src-toolbar" role="group" aria-label="筛选信源">${[['all','全部来源'],['hotlist','舆情热榜'],['content','内容榜单'],['other','公共信息 / 参考']].map(([k,n])=>`<button class="src-filter ${(native.sourceFilter||'all')===k?'on':''}" onclick="wfSourceFilter('${k}')">${n}</button>`).join('')}<button class="btn" onclick="v4Go('crawl')">查看采集流水</button></div><div class="src-grid">${visible.map(s=>{const [label,cls]=tag(s),last=latest.find(x=>x.provider===s.provider&&x.source_id===s.source_id);return `<article class="src-card ${cls==='ok'?'success':cls==='bad'?'failed':''}"><div class="wf-between"><h3>${liveEsc(s.title)}</h3><span class="src-state ${cls}">${label}</span></div><div class="src-url">${liveEsc(s.origin)} · ${liveEsc(s.provider)} / ${liveEsc(s.source_id)}</div><div class="src-meta"><span class="src-pill">${s.kind==='hotlist'?'舆情热榜':s.kind==='content_rank'?'内容榜单':s.kind==='public_notice'?'公共信息':'参考数据'}</span><span class="src-pill">指标：${liveEsc(s.metric||'未注明')}</span><span class="src-pill">TypeScript 原生采集</span></div><div class="src-detail">${last?`最近一次：${liveEsc(liveStamp(last.observed_at))} · ${last.status==='succeeded'?`取得 ${last.item_count} 条`:`失败：${liveEsc(last.error||'来源无返回')}`}`:'尚未执行真实采集，因此连接状态、返回条数和热度字段均待实测。'}</div><div class="src-meta"><button class="btn" onclick="wf.recordSource='${liveEsc(s.provider+':'+s.source_id)}';v4Go('crawl')">查看执行记录</button></div></article>`;}).join('')}</div><h3 class="src-section">研究检索 / 抓取服务（独立于热榜渠道）</h3><div class="src-note">这里的服务凭据状态不代表接口调用已经成功；服务实测结果需在研究任务中产生真实调用记录。</div><div class="src-services">${native.services.map(s=>`<article class="src-service"><div class="wf-between"><b>${liveEsc(s.id)}</b><span class="src-state ${s.enabled&&s.key_configured?'pending':''}">${s.enabled?(s.key_configured?'已配置，未实测':'已启用，缺少凭据'):'未启用'}</span></div><div class="src-detail">${liveEsc(s.base_url||'端点未配置')}</div><button class="btn" onclick="v4Go('keys')">配置服务</button></article>`).join('')}</div>`;};
const sourceRendererBeforeAction=wfSources;wfSources=function(){sourceRendererBeforeAction();const cards=[...document.querySelectorAll('#p-src .src-card')],rows=native.sources?.configured||[];for(const card of cards){const text=card.querySelector('.src-url')?.textContent||'',source=rows.find(s=>text.includes(`${s.provider} / ${s.source_id}`));if(source){if(source.health!=='not_tested')card.querySelector('.src-meta')?.insertAdjacentHTML('beforeend',`<span class="src-pill">本次带指标 ${source.metric_count??0}/${source.item_count??0} 条</span>`);card.querySelector('.src-meta:last-child')?.insertAdjacentHTML('beforeend',`<button class="btn" onclick="nativeCollectSource('${source.provider}','${source.source_id}')">立即采集 / 复测</button>`);}}};
async function nativeCollectSource(provider,id){try{showToast(`正在采集 ${id}，会留下快照和采集流水`);const result=await liveApi('/hotlists/collect','POST',{provider,source_ids:[id]});await nativeSync();wfSources();const row=result.snapshots?.[0];showToast(row?.status==='succeeded'?`${id} 采集成功：${row.item_count} 条`:`${id} 采集失败：${row?.error||'查看采集流水'}`);}catch(e){liveError(e);}}

function nativeSamplingPanel(){const s=native.sampling||{};return `<section class="native-card" style="--accent:#5277c8;margin:20px 0"><h3>MiniLM 语义聚类抽样</h3>${v4Tag(s.installed?"本地模型已安装":"未安装，明确回退",s.installed?"g":"gr")}<p class="native-meta">${liveEsc(s.model_id||"paraphrase-multilingual-MiniLM-L12-v2")} · TypeScript / ONNX q8，无云端 Token。</p><p class="native-meta">${liveEsc(s.note||"")} KMeans 使用 seed 42、10 次初始化，每簇最多保留 5 条代表材料；200 条候选中最多返回 30 条。完整归档和抽样过程均保留。报告中的词组 Jaccard 聚类另行标识，不冒充语义模型结果。</p></section>`;}
